window.HOEREN_TESTS[86] = {"id":"im-spielzeugladen","name":"Im Spielzeugladen","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Vor Weihnachten ist viel los in unserem Spielzeugladen. Die beliebten Puppen sind fast ausverkauft, aber wir bekommen am Freitag neue. Die großen Holzeisenbahnen sind noch da, und Bücher haben wir auch genug. Bestellen Sie früh, damit das Geschenk rechtzeitig kommt. Wir wünschen schöne Feiertage!","gender":"f","q":"Was ist fast ausverkauft?","opts":["Die Holzeisenbahnen.","Die Puppen.","Die Bücher."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Pass auf, meine Tochter wird fünf und wünscht sich ein Fahrrad. Ich war im Spielzeugladen, aber ich weiß nicht, welche Größe passt. Du hast doch auch eine kleine Tochter. Welches Fahrrad habt ihr gekauft? Ruf zurück, der Geburtstag ist schon nächste Woche. Danke!","gender":"m","q":"Was wünscht sich die Tochter?","opts":["Ein Fahrrad.","Eine Puppe.","Ein Spiel."],"correct":0},{"transcript":"Achtung Eltern: Bitte achten Sie beim Kauf auf die Altersangabe, nicht nur auf den Preis oder die Farbe. Kleine Teile sind für Kinder unter drei Jahren gefährlich, sie können sie verschlucken. Auf jeder Verpackung steht das passende Alter. Unsere Mitarbeiter beraten Sie gern. Sicherheit geht vor Spaß. Vielen Dank für Ihr Verständnis!","gender":"m","q":"Worauf sollen Eltern achten?","opts":["Auf die Altersangabe.","Auf den Preis.","Auf die Farbe."],"correct":0},{"transcript":"Hi Lisa, hier ist Anna. Ich habe für den Geburtstag meines Neffen ein tolles Geschenk gefunden — ein Baukasten mit hundert Teilen. Er baut so gern! Aber es war teuer, 40 Euro. Glaubst du, das ist zu viel? Er ist mein Lieblingsneffe. Sag mir deine Meinung, bis bald!","gender":"f","q":"Was hat Anna gekauft?","opts":["Ein Fahrrad.","Einen Baukasten.","Ein Buch."],"correct":1},{"transcript":"Liebe Kunden: Wir bieten jetzt auch Spielzeug zum Leihen an. Große Sachen wie Rutschen oder Spielhäuser können Sie für eine Party mieten, statt sie teuer zu kaufen. Das spart Geld und Platz zu Hause. Fragen Sie an der Kasse nach den Preisen. Eine tolle Idee für Kindergeburtstage!","gender":"f","q":"Was kann man jetzt leihen?","opts":["Puppen.","Bücher.","Große Sachen wie Rutschen."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kauft was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Feier für die Kinder ist am Samstag. Was kaufen wir im Laden?"},{"speaker":"Lisa","gender":"f","text":"Ich habe fünf Wünsche auf dem Zettel. Jedes Kind soll sich wirklich freuen."},{"speaker":"Lukas","gender":"m","text":"Ich weiß schon was ich nehme. Ich kaufe die große Eisenbahn aus Holz."},{"speaker":"Lisa","gender":"f","text":"Die steht im Fenster. Kauft jemand ein Fahrrad?"},{"speaker":"Lukas","gender":"m","text":"Ein Fahrrad kauft heute keiner. Das Geld reicht nicht."},{"speaker":"Lisa","gender":"f","text":"Ich kaufe die Puppe mit dem roten Kleid."},{"speaker":"Lukas","gender":"m","text":"Die sitzt direkt am Fenster. Was wünscht sich Tom?"},{"speaker":"Lisa","gender":"f","text":"Tom wünscht sich einen Baukasten. Er baut gern hohe Häuser."},{"speaker":"Lukas","gender":"m","text":"Den finden wir hinten. Will jemand ein Puzzle mit tausend Teilen?"},{"speaker":"Lisa","gender":"f","text":"Ein Puzzle will auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara spielt gern am Tisch mit der ganzen Familie."},{"speaker":"Lisa","gender":"f","text":"Sara wünscht sich ein Brettspiel. Abends wollen alle es zusammen spielen."},{"speaker":"Lukas","gender":"m","text":"Das liegt neben der Kasse. Tim ist noch klein und mag weiche Sachen."},{"speaker":"Lisa","gender":"f","text":"Tim wünscht sich ein Kuscheltier für das Bett."},{"speaker":"Lukas","gender":"m","text":"Das liegt unten."},{"speaker":"Lisa","gender":"f","text":"Ich lege unsere fünf Sachen auf den Tisch."}],"options":[{"letter":"a","text":"Baukasten"},{"letter":"b","text":"Auto"},{"letter":"c","text":"Eisenbahn"},{"letter":"d","text":"Puppe"},{"letter":"e","text":"Fahrrad"},{"letter":"f","text":"Kuscheltier"},{"letter":"g","text":"Ball"},{"letter":"h","text":"Puzzle"},{"letter":"i","text":"Brettspiel"}],"items":[{"person":"Lukas","correct":"c"},{"person":"Lisa","correct":"d"},{"person":"Tom","correct":"a"},{"person":"Sara","correct":"i"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, für welches Alter ist dieses Spiel? Ab vier, ab sechs oder ab acht?"},{"speaker":"Verkäufer","gender":"m","text":"Ab sechs Jahren. Ab vier ist es zu schwer, ab acht oft zu leicht."},{"speaker":"Kundin","gender":"f","text":"Mein Sohn ist erst vier. Dann ist sechs zu alt?"},{"speaker":"Verkäufer","gender":"m","text":"Ja, nehmen Sie lieber dieses hier, das ist ab vier. Nicht das ab sechs und nicht das ab acht."},{"speaker":"Kundin","gender":"f","text":"Danke, dann das für vier Jahre. Das andere ist ab sechs."}],"q":"Ab welchem Alter ist das erste Spiel?","opts":["Ab sechs Jahren.","Ab vier Jahren.","Ab acht Jahren."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Was kostet diese Puppe? 25 Euro, oder schon 45?"},{"speaker":"Verkäuferin","gender":"f","text":"Die Puppe allein 25 Euro. 45 Euro wäre mit Haus und Auto, das brauchen Sie nicht."},{"speaker":"Mann","gender":"m","text":"Und mit Kleidung? Ist das Set 35 oder 45?"},{"speaker":"Verkäuferin","gender":"f","text":"Das Set mit Kleidung kostet 35 Euro, nicht 25 und nicht 45. Die Kleidung ist dabei."},{"speaker":"Mann","gender":"m","text":"Gut, dann das Set für 35 Euro. Danke."}],"q":"Was kostet das Set mit Kleidung?","opts":["25 Euro.","35 Euro.","45 Euro."],"correct":1},{"lines":[{"speaker":"Großmutter","gender":"f","text":"Ich suche etwas für ein Baby. Kein Brettspiel und kein Fahrrad, das ist zu früh."},{"speaker":"Verkäufer","gender":"m","text":"Wie alt ist das Baby? Ein Brettspiel und ein Fahrrad sind wirklich nichts für Babys."},{"speaker":"Großmutter","gender":"f","text":"Acht Monate. Also wirklich kein Brettspiel und kein Fahrrad."},{"speaker":"Verkäufer","gender":"m","text":"Dann etwas Weiches ohne kleine Teile. Kein Brettspiel, kein Fahrrad, nur weich und sicher."},{"speaker":"Großmutter","gender":"f","text":"Perfekt, dann nehme ich das Weiche. Danke."}],"q":"Was empfiehlt der Verkäufer?","opts":["Ein Fahrrad.","Ein Brettspiel.","Etwas Weiches ohne kleine Teile."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Können Sie das Geschenk einpacken? Kostet das 2 Euro oder 5 Euro?"},{"speaker":"Verkäuferin","gender":"f","text":"Gern, das ist kostenlos. Nicht 2 Euro und nicht 5 Euro, das Einpacken ist umsonst."},{"speaker":"Kunde","gender":"m","text":"Mit einer Schleife? Wirklich kostenlos, nicht 2 Euro?"},{"speaker":"Verkäuferin","gender":"f","text":"Natürlich, welche Farbe? Es bleibt kostenlos, kein Aufpreis von 2 oder 5 Euro."},{"speaker":"Kunde","gender":"m","text":"Dann rot, bitte. Danke, dass es kostenlos ist."}],"q":"Was kostet das Einpacken?","opts":["2 Euro.","Es ist kostenlos.","5 Euro."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Das Spielzeug ist schon kaputt. Reparieren Sie es, oder geben Sie kein Geld zurück?"},{"speaker":"Verkäufer","gender":"m","text":"Seit wann haben Sie es? Reparieren können wir hier nicht, und ohne Prüfung geben wir kein Geld zurück."},{"speaker":"Frau","gender":"f","text":"Erst seit gestern. Also tauschen Sie um, oder was dann?"},{"speaker":"Verkäufer","gender":"m","text":"Dann tausche ich es sofort um. Ich repariere es nicht, und Sie bekommen kein Geld, sondern ein neues Spielzeug."},{"speaker":"Frau","gender":"f","text":"Gut, dann den Umtausch. Danke."}],"q":"Was macht der Verkäufer?","opts":["Er tauscht es um.","Er repariert es.","Er gibt das Geld zurück."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Berg, einer Spielzeughändlerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Berg, hat sich das Spielzeug in den letzten Jahren verändert?"},{"speaker":"Berg","gender":"f","text":"Ja, sehr, früher gab es einfaches Holzspielzeug. Heute hat alles oft Elektronik. Manche Kinder mögen beides, Holz und Technik."},{"speaker":"Reporter","gender":"m","text":"Was kaufen die Leute am häufigsten, und wann ist am meisten los?"},{"speaker":"Berg","gender":"f","text":"Vor Weihnachten ist am meisten los, das Geschäft ist dann voll. Beliebt sind Baukästen und Brettspiele, die kaufen viele Familien."},{"speaker":"Reporter","gender":"m","text":"Worauf achten Sie bei Ihrem Spielzeug? Auf den Preis allein?"},{"speaker":"Berg","gender":"f","text":"Auf gute Qualität und Sicherheit. Billiges Spielzeug geht schnell kaputt. Ich achte also sehr auf Qualität und Sicherheit, nicht nur auf den Preis."},{"speaker":"Reporter","gender":"m","text":"Geben die Eltern zu viel Geld aus für Spielzeug?"},{"speaker":"Berg","gender":"f","text":"Manchmal ja. Kinder brauchen nicht so viel. Wenige gute Sachen sind besser als viele billige. Das sage ich den Eltern oft."},{"speaker":"Reporter","gender":"m","text":"Was ist das Schönste an Ihrem Beruf?"},{"speaker":"Berg","gender":"f","text":"Die glücklichen Kinder. Wenn ein Kind staunt, freue ich mich. Die glücklichen Kinder sind mir sehr wichtig, ohne sie wäre der Laden leer. Deshalb arbeite ich gern hier, auch vor Weihnachten, wenn es stressig ist. Das Lachen der Kinder ist der schönste Lohn."}],"items":[{"q":"Heute hat das Spielzeug oft Elektronik.","correct":"ja"},{"q":"Vor Weihnachten ist am meisten los.","correct":"ja"},{"q":"Frau Berg achtet nicht auf Qualität und Sicherheit.","correct":"nein"},{"q":"Sie sagt, wenige gute Sachen sind besser als viele.","correct":"ja"},{"q":"Sie findet die glücklichen Kinder nicht wichtig.","correct":"nein"}]}]};
